    matching_holiday = holidays.find { |hol| hol[:name] == "Año Nuevo" }
    assert_not_nil matching_holiday
    assert_equal Date.civil(2026, 1, 1), matching_holiday[:date]
    assert_includes matching_holiday[:regions], :hn


